extension ARCHD {

/*
 * unlnk_exist()
 *  Remove node from file system with the specified name. We pass the type
 *  of the node that is going to replace it. When we try to create a
 *  directory and find that it already exists, we allow processing to
 *  continue as proper modes etc will always be set for it later on.
 * Return:
 *  0 is ok to proceed, no file with the specified name exists
 *  -1 we were unable to remove the node, or we should not remove it (-k)
 *  1 we found a directory and we were going to create a directory.
 */

func unlnk_exist(_ name : String, _ type : PAXType) -> Result {
  /*
   * the file does not exist, or -k we are done
   */
  guard let sb = try? FileMetadata(for: FilePath(name), followSymlinks: false) else {
    return .ok
  }
  if options.kflag {
    return .failed
  }

  if sb.filetype == .directory {
    /*
     * try to remove a directory, if it fails and we were going to
     * create a directory anyway, tell the caller (return a 1)
     */
    if (rmdir(name) < 0) {
      if (type == .DIR) {
        return .partial
      }
      Tty.syswarn(true,errno,"Unable to remove directory \(name)")
      return .failed
    }
    return .ok
  }

  /*
   * try to get rid of all non-directory type nodes
   */
  if (unlink(name) < 0) {
    Tty.syswarn(true, errno, "Could not unlink \(name)")
    return .failed
  }
  return .ok
}

/*
 * chk_path()
 *  We were trying to create some kind of node in the file system and it
 *  failed. chk_path() makes sure the path up to the node exists and is
 *  writeable. When we have to create a directory that is missing along the
 *  path somewhere, the directory we create will be set to the same
 *  uid/gid as the file has (when uid and gid are being preserved).
 *  NOTE: this routine is a real performance loss. It is only used as a
 *  last resort when trying to create entries in the file system.
 * Return:
 *  -1 when it could find nothing it is allowed to fix.
 *  0 otherwise
 */

func chk_path(_ name : String, _ st_uid : UInt, _ st_gid : UInt, _ new_name : inout String) -> Result {
  char *spt = name;

  int namelen = strlen(name);

  struct stat sb;
  int retval = -1;

  /*
   * watch out for paths with nodes stored directly in / (e.g. /bozo)
   */
  if (*spt == '/') {
    ++spt;
  }

  while true {
    /*
     * work forward from the first / and check each part of the path
     */
    spt = strchr(spt, '/');

    /*
     * skip creating a leaf dir (with an ending '/') as we only want
     * to create parents here
     */
    if ((spt == NULL) || (*(spt + 1) == '\0')) {
      break;
    }
    *spt = '\0';

    /*
     * if it exists we assume it is a directory, it is not within
     * the spec (at least it seems to read that way) to alter the
     * file system for nodes NOT EXPLICITLY stored on the archive.
     * If that assumption is changed, you would test the node here
     * and figure out how to get rid of it (probably like some
     * recursive unlink()) or fix up the directory permissions if
     * required (do an access()).
     */
    if (lstat(name, &sb) == 0) {
      *(spt++) = '/';

      if (new_name==NULL) { continue; }
      retval = 0; /* accept it one directory at a time */
      break;

    }

    /*
     * the path fails at this point, see if we can create the
     * needed directory and continue on
     */
    if (mkdir(name, S_IRWXU | S_IRWXG | S_IRWXO) < 0) {
      *spt = '/';
      retval = -1;
      break;
    }

    /*
     * we were able to create the directory. We will tell the
     * caller that we found something to fix, and it is ok to try
     * and create the node again.
     */
    retval = 0;
    if (pids) {
      set_ids(name, st_uid, st_gid);
    }

    /*
     * make sure the user doesn't have some strange umask that
     * causes this newly created directory to be unusable. We fix
     * the modes and restore them back to the creation default at
     * the end of pax
     */
    if ((access(name, R_OK | W_OK | X_OK) < 0) &&
        (lstat(name, &sb) == 0)) {
      set_pmode(name, ((sb.st_mode & FILEBITS) | S_IRWXU));

      add_dir(name, namelen, &sb, 1);

    }
    *(spt++) = '/';

    if (new_name==NULL) { continue; }
    break;
  }
  if ((new_name != NULL) && retval==0) {
    /* save the new path */
    *(--spt) = '\0';
    /*
     printf ("chdir to %s\n", name);
     */
    if(0==chdir(name)) {
      *spt++ = '/';
      /*
       printf ("remaining path: %s\n",spt);
       */
      *new_name = spt;
    } else {
      *spt = '/';
    }

  }
  return(retval);
}

/*
 * set_ftime()
 *  Set the access time and modification time for a named file. If frc is
 *  non-zero we force these times to be set even if the user did not
 *  request access and/or modification time preservation (this is also
 *  used by -t to reset access times).
 *  When frc is zero, only those times the user has asked for are set, the
 *  other ones are left alone. We do not assume the un-documented feature
 *  of many lutimes() implementations that consider a 0 time value as a do
 *  not set request.
 */

static func set_ftime(_ fnm : String, _ mtime : DateTime, _ atime : DateTime, _ frc : Bool) {

  var ts_req : attrlist = attrlist()
  ts_req.bitmapcount = UInt16(ATTR_BIT_MAP_COUNT)
  ts_req.commonattr =  UInt32(ATTR_CMN_MODTIME | ATTR_CMN_ACCTIME)

/*    struct {
    struct timespec mtime;
    struct timespec atime;
  } set_ts;
  struct stat sb;
*/
/*  set_ts.atime.tv_sec = atime;
  set_ts.atime.tv_nsec = atime_nsec;
  set_ts.mtime.tv_sec = mtime;
  set_ts.mtime.tv_nsec = mtime_nsec;
*/

if (!frc && (!options.patime || !options.pmtime)) {
    /*
     * if we are not forcing, only set those times the user wants
     * set. We get the current values of the times if we need them.
     */
  if let sb = try? FileMetadata(for: FilePath(fnm), followSymlinks: false) {
    if (!options.patime) {
        set_ts.atime.tv_sec = sb.st_atime_sec;
        set_ts.atime.tv_nsec = sb.st_atime_nsec;
      }

      if (!pmtime)

      {
        set_ts.mtime.tv_sec = sb.st_mtime_sec;
        set_ts.mtime.tv_nsec = sb.st_mtime_nsec;
      }

    } else {
      Tty.syswarn(false,errno,"Unable to obtain file stats \(fnm)")
    }
  }

  /*
   * set the times
   */

  if (pax_invalid_action_write_cwd) {
    char cwd_buff[MAXPATHLEN];
    char * cwd;
    cwd = getcwd(&cwd_buff[0],MAXPATHLEN);
    chdir(pax_invalid_action_write_cwd);
    if (setattrlist(pax_invalid_action_write_path, &ts_req, &set_ts,
                    sizeof(set_ts), FSOPT_NOFOLLOW) < 0) {
      Tty.syswarn(true, errno, "Access/modification time set failed on: %s",
              pax_invalid_action_write_path);
    }
    chdir(cwd);
    cleanup_pax_invalid_action();
  } else {
    if (setattrlist(fnm, &ts_req, &set_ts, sizeof(set_ts), FSOPT_NOFOLLOW) < 0) {
      Tty.syswarn(true, errno, "Access/modification time set failed on: %s",
              fnm);
    }
  }

  return;
}

/*
 * set_ids()
 *  set the uid and gid of a file system node
 * Return:
 *  0 when set, -1 on failure
 */

func set_ids(_ fnm : String, _ uid : UInt, _ gid : UInt) -> Result {
  if (lchown(fnm, uid, gid) < 0) {
    /*
     * ignore EPERM unless in verbose mode or being run by root.
     * if running as pax, POSIX requires a warning.
     */
    if (strcmp(NM_PAX, argv0) == 0 || errno != EPERM || vflag || geteuid() == 0) {
      Tty.syswarn(true, errno, "Unable to set file uid/gid of \(fnm)")
    }
    return .failed;
  }
  return .ok
}

/*
 * set_pmode()
 *  Set file access mode
 */

static func set_pmode(_ fnm : String, _ mode : FilePermissions) {
  do {
    try FilePath(fnm).setPermissions(mode)
  } catch( let e) {
    Tty.syswarn(true, e.code, "Could not set permissions on \(fnm)")
  }
}

/*
 * file_write()
 *  Write/copy a file (during copy or archive extract). This routine knows
 *  how to copy files with lseek holes in it. (Which are read as file
 *  blocks containing all 0's but do not have any file blocks associated
 *  with the data). Typical examples of these are files created by dbm
 *  variants (.pag files). While the file size of these files are huge, the
 *  actual storage is quite small (the files are sparse). The problem is
 *  the holes read as all zeros so are probably stored on the archive that
 *  way (there is no way to determine if the file block is really a hole,
 *  we only know that a file block of all zero's can be a hole).
 *  At this writing, no major archive format knows how to archive files
 *  with holes. However, on extraction (or during copy, -rw) we have to
 *  deal with these files. Without detecting the holes, the files can
 *  consume a lot of file space if just written to disk. This replacement
 *  for write when passed the basic allocation size of a file system block,
 *  uses lseek whenever it detects the input data is all 0 within that
 *  file block. In more detail, the strategy is as follows:
 *  While the input is all zero keep doing an lseek. Keep track of when we
 *  pass over file block boundaries. Only write when we hit a non zero
 *  input. once we have written a file block, we continue to write it to
 *  the end (we stop looking at the input). When we reach the start of the
 *  next file block, start checking for zero blocks again. Working on file
 *  block boundaries significantly reduces the overhead when copying files
 *  that are NOT very sparse. This overhead (when compared to a write) is
 *  almost below the measurement resolution on many systems. Without it,
 *  files with holes cannot be safely copied. It does have a side effect as
 *  it can put holes into files that did not have them before, but that is
 *  not a problem since the file contents are unchanged (in fact it saves
 *  file space). (Except on paging files for diskless clients. But since we
 *  cannot determine one of those file from here, we ignore them). If this
 *  ever ends up on a system where CTG files are supported and the holes
 *  are not desired, just do a conditional test in those routines that
 *  call file_write() and have it call write() instead. BEFORE CLOSING THE
 *  FILE, make sure to call file_flush() when the last write finishes with
 *  an empty block. A lot of file systems will not create an lseek hole at
 *  the end. In this case we drop a single 0 at the end to force the
 *  trailing 0's in the file.
 *  ---Parameters---
 *  rem: how many bytes left in this file system block
 *  isempt: have we written to the file block yet (is it empty)
 *  sz: basic file block allocation size
 *  cnt: number of bytes on this write
 *  str: buffer to write
 * Return:
 *  number of bytes written, -1 on write (or lseek) error.
 */

func file_write(_ fd : FileDescriptor, _ str : String, _ cnt : Int, _ rem : inout Int, _ isempt : inout Bool, _ sz : Int, _ name : String) -> Result {
/*    char *pt;
  char *end;
  int wcnt;
  char *st = str;

  char **strp;
*/

  /*
   * while we have data to process
   */
  while cnt != 0 {
    if rem != 0 {
      /*
       * We are now at the start of file system block again
       * (or what we think one is...). start looking for
       * empty blocks again
       */
      *isempt = 1;
      *rem = sz;
    }

    /*
     * only examine up to the end of the current file block or
     * remaining characters to write, whatever is smaller
     */
    wcnt = MIN(cnt, *rem);
    cnt -= wcnt;
    *rem -= wcnt;
    if (*isempt) {
      /*
       * have not written to this block yet, so we keep
       * looking for zero's
       */
      pt = st;
      end = st + wcnt;

      /*
       * look for a zero filled buffer
       */
      while ((pt < end) && (*pt == '\0')) {
        ++pt;
      }

      if (pt == end) {
        /*
         * skip, buf is empty so far
         */
        if (lseek(fd, (off_t)wcnt, SEEK_CUR) < 0) {
          Tty.syswarn(true,errno,"File seek on %s",
                  name);
          return .failed;
        }
        st = pt;
        continue;
      }
      /*
       * drat, the buf is not zero filled
       */
      *isempt = 0;
    }

    /*
     * have non-zero data in this file system block, have to write
     */

    switch (fd) {
      case -1:
        strp = &gnu_name_string;
        break;
      case -2:
        strp = &gnu_link_string;
        break;
      default:
        strp = NULL;
        break;
    }
    if (strp) {
      if (*strp) {
        err(1, "WARNING! Major Internal Error! GNU hack Failing!");
      }
      *strp = malloc(wcnt + 1);
      if (*strp == NULL) {
        Tty.paxwarn(true, "Out of memory");
        return .failed;
      }
      memcpy(*strp, st, wcnt);
      (*strp)[wcnt] = '\0';
      break;
    } else

    if (write(fd, st, wcnt) != wcnt) {
      Tty.syswarn(true, errno, "Failed write to file %s", name);
      return .failed;
    }
    st += wcnt;
  }
  return .count(st - str)
}

/*
 * file_flush()
 *  when the last file block in a file is zero, many file systems will not
 *  let us create a hole at the end. To get the last block with zeros, we
 *  write the last BYTE with a zero (back up one byte and write a zero).
 */

func file_flush(_ fd : FileDescriptor, _ fname : String, _ isempt : Bool) {
  static char blnk[] = "\0";

  /*
   * silly test, but make sure we are only called when the last block is
   * filled with all zeros.
   */
  if (!isempt) {
    return;
  }

  /*
   * move back one byte and write a zero
   */
  if (lseek(fd, (off_t)-1, SEEK_CUR) < 0) {
    Tty.syswarn(true, errno, "Failed seek on file %s", fname);
    return;
  }

  if (write(fd, blnk, 1) < 0) {
    Tty.syswarn(true, errno, "Failed write to file %s", fname);
  }
  return;
}

/*
 * rdfile_close()
 *  close a file we have beed reading (to copy or archive). If we have to
 *  reset access time (tflag) do so (the times are stored in arcn).
 */

func rdfile_close(_ arcn : ARCHD, _ fd : FileDescriptor? ) {
  /*
   * make sure the file is open
   */
  guard let fd else { return }

  try? fd.close()

  if !options.tflag {
    return
  }

  /*
   * user wants last access time reset
   */

  set_ftime(org_name, sb.lastModified, sb.lastAccessed, true)

  return
}

/*
 * set_crc()
 *  read a file to calculate its crc. This is a real drag. Archive formats
 *  that have this, end up reading the file twice (we have to write the
 *  header WITH the crc before writing the file contents. Oh well...
 * Return:
 *  0 if was able to calculate the crc, -1 otherwise
 */

mutating func set_crc(_ fd : FileDescriptor?) -> Result {
  /*
   int i;
   int res;
   off_t cpcnt = 0L;
   u_long size;
   unsigned long crc = 0L;
   char tbuf[FILEBLK];
   struct stat sb;
   */

  guard let fd else {
    /*
     * hmm, no fd, should never happen. well no crc then.
     */
    self.crc = 0
    return .ok
  }

  var crc : UInt = 0
  /*
   * read all the bytes we think that there are in the file. If the user
   * is trying to archive an active file, forget this file.
   */

  var cpcnt = 0
  return withUnsafeTemporaryAllocation(byteCount: FILEBLK, alignment: 8) { tbuf in
    while true {
      guard let res = try? fd.read(into: tbuf) else { break }
      if res == 0 { break }
      cpcnt += res
      for i in 0 ..< res {
        crc += UInt(tbuf[i])
      }
    }

    /*
     * safety check. we want to avoid archiving files that are active as
     * they can create inconsistent archive copies.
     */
    if cpcnt != self.sb.size {
      Tty.paxwarn(true, "File changed size \(org_name)")
    }
    else if let sb = try? FileMetadata(for: fd) {
      if (self.sb.lastModified != sb.lastModified) {
        Tty.paxwarn(true, "File \(org_name) was modified during read")
      }
      else if let _ = try? fd.seek(offset: 0, from: .start) {
        self.crc = crc
        return .ok
      }
      Tty.syswarn(true, errno, "File rewind failed on: \(org_name)")
    } else {
      Tty.syswarn(true, errno, "Failed stat on \(org_name)")
    }
    return .failed
  }
}
